"""Short code generation, validation, cache, rate limiting and async analytics."""
import re
import string
import threading
import time
import queue
from collections import OrderedDict
from datetime import datetime
from urllib.parse import urlparse

BASE62 = string.digits + string.ascii_lowercase + string.ascii_uppercase
CUSTOM_ALIAS_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")


def encode_base62(num):
    if num <= 0:
        return BASE62[0]
    digits = []
    while num:
        num, rem = divmod(num, 62)
        digits.append(BASE62[rem])
    return "".join(reversed(digits))


def validate_long_url(url):
    if not isinstance(url, str) or len(url) > 4096:
        return False
    try:
        p = urlparse(url)
    except Exception:
        return False
    return p.scheme in ("http", "https") and bool(p.netloc)


def validate_custom_alias(alias):
    return isinstance(alias, str) and bool(CUSTOM_ALIAS_RE.match(alias))


def validate_expiry(expires_at):
    if expires_at is None:
        return True
    try:
        datetime.fromisoformat(str(expires_at).replace("Z", "+00:00"))
        return True
    except Exception:
        return False


class LRUCache:
    def __init__(self, capacity=1000):
        self.capacity = capacity
        self.data = OrderedDict()
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key not in self.data:
                return None
            self.data.move_to_end(key)
            return self.data[key]

    def set(self, key, value):
        with self.lock:
            self.data[key] = value
            self.data.move_to_end(key)
            if len(self.data) > self.capacity:
                self.data.popitem(last=False)

    def invalidate(self, key):
        with self.lock:
            self.data.pop(key, None)


class TokenBucketLimiter:
    def __init__(self, rate=50.0, capacity=100.0):
        self.rate = rate
        self.capacity = capacity
        self.buckets = {}
        self.lock = threading.Lock()

    def allow(self, identifier):
        now = time.monotonic()
        with self.lock:
            tokens, last = self.buckets.get(identifier, (self.capacity, now))
            tokens = min(self.capacity, tokens + (now - last) * self.rate)
            if tokens < 1.0:
                self.buckets[identifier] = (tokens, now)
                return False
            tokens -= 1.0
            self.buckets[identifier] = (tokens, now)
            return True


class AnalyticsPipeline:
    """Buffers click events and flushes them in batches to storage."""

    def __init__(self, storage, flush_interval=1.0):
        self.storage = storage
        self.q = queue.Queue()
        self.flush_interval = flush_interval
        self._stop = threading.Event()
        self.thread = threading.Thread(target=self._run, daemon=True)
        self.thread.start()

    def record(self, short_code, clicked_at, referrer, user_agent, device, geo_country):
        self.q.put((short_code, clicked_at, referrer, user_agent, device, geo_country))

    def _drain(self):
        events = []
        try:
            while True:
                events.append(self.q.get_nowait())
        except queue.Empty:
            pass
        return events

    def _apply(self, events):
        if not events:
            return
        self.storage.insert_clicks_batch(events)
        daily = {}
        for e in events:
            day = e[1][:10]
            daily[(e[0], day)] = daily.get((e[0], day), 0) + 1
        for (code, day), cnt in daily.items():
            self.storage.upsert_daily_aggregate(code, day, cnt)

    def _run(self):
        while not self._stop.is_set():
            self._apply(self._drain())
            self._stop.wait(self.flush_interval)

    def flush_now(self):
        self._apply(self._drain())

    def stop(self):
        self._stop.set()

"""Core application logic tying together storage, cache and analytics."""
import time
from datetime import datetime, timezone

from .storage import Storage
from .core import (
    encode_base62,
    validate_long_url,
    validate_custom_alias,
    validate_expiry,
    LRUCache,
    TokenBucketLimiter,
    AnalyticsPipeline,
)

DOMAIN = "https://short.ly"


def now_iso():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


class Application:
    def __init__(self, db_path=":memory:"):
        self.storage = Storage(db_path)
        self.cache = LRUCache(capacity=10000)
        self.limiter = TokenBucketLimiter(rate=50, capacity=100)
        self.analytics = AnalyticsPipeline(self.storage, flush_interval=0.2)

    def create_url(self, body, owner_key=None):
        long_url = body.get("long_url") or body.get("url")
        custom_alias = body.get("custom_alias")
        expires_at = body.get("expires_at")

        if not long_url or not validate_long_url(long_url):
            return 400, {"error": "invalid long_url"}
        if expires_at is not None and not validate_expiry(expires_at):
            return 400, {"error": "invalid expires_at"}

        created_at = now_iso()

        if custom_alias:
            if not validate_custom_alias(custom_alias):
                return 400, {"error": "invalid custom_alias"}
            ok = self.storage.insert_url(
                custom_alias, long_url, owner_key, created_at, expires_at, True
            )
            if not ok:
                return 409, {"error": "alias already taken"}
            short_code = custom_alias
        else:
            short_code = None
            for attempt in range(5):
                candidate_id = self.storage.next_id() + attempt + int(time.time() * 1000) % 997
                candidate = encode_base62(candidate_id)
                if self.storage.insert_url(
                    candidate, long_url, owner_key, created_at, expires_at, False
                ):
                    short_code = candidate
                    break
            if short_code is None:
                return 500, {"error": "failed to allocate short code"}

        self.cache.set(short_code, long_url)
        return 201, {
            "short_code": short_code,
            "short_url": f"{DOMAIN}/{short_code}",
            "long_url": long_url,
            "expires_at": expires_at,
            "created_at": created_at,
        }

    def resolve(self, short_code):
        cached = self.cache.get(short_code)
        row = self.storage.get_url(short_code)
        if row is None:
            return None
        if row["expires_at"] and row["expires_at"] < now_iso():
            self.cache.invalidate(short_code)
            return "EXPIRED"
        if cached is None:
            self.cache.set(short_code, row["long_url"])
        return row["long_url"]

    def record_click(self, short_code, referrer, user_agent, geo_country="US"):
        device = "mobile" if user_agent and "Mobile" in user_agent else "desktop"
        self.analytics.record(short_code, now_iso(), referrer, user_agent, device, geo_country)

    def get_url_info(self, short_code):
        row = self.storage.get_url(short_code)
        if row is None:
            return 404, {"error": "not found"}
        owner = None
        if row["owner_key"]:
            owner = self.storage.get_api_key_owner(row["owner_key"]) or row["owner_key"]
        return 200, {
            "short_code": row["short_code"],
            "long_url": row["long_url"],
            "created_at": row["created_at"],
            "expires_at": row["expires_at"],
            "owner": owner,
            "click_count": row["click_count"],
        }

    def delete_url(self, short_code):
        ok = self.storage.delete_url(short_code)
        self.cache.invalidate(short_code)
        if not ok:
            return 404, {"error": "not found"}
        return 200, {"short_code": short_code, "status": "deleted"}

    def get_analytics(self, short_code):
        row = self.storage.get_url(short_code)
        if row is None:
            return 404, {"error": "not found"}
        self.analytics.flush_now()
        row = self.storage.get_url(short_code)
        daily = self.storage.get_daily_aggregates(short_code)
        recent = self.storage.get_recent_clicks(short_code, limit=10)
        return 200, {
            "short_code": short_code,
            "total_clicks": row["click_count"],
            "daily": daily,
            "recent_events": recent,
        }

    def shutdown(self):
        self.analytics.stop()

"""HTTP API layer using only the standard library http.server module."""
import json
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .app import Application

ANALYTICS_RE = re.compile(r"^/api/urls/([^/]+)/analytics$")
URL_ITEM_RE = re.compile(r"^/api/urls/([^/]+)$")


class Handler(BaseHTTPRequestHandler):
    app = None

    def _send(self, status, payload):
        body = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _client_id(self):
        return self.headers.get("X-API-Key") or self.client_address[0]

    def do_POST(self):
        if self.path == "/api/urls":
            if not self.app.limiter.allow(self._client_id()):
                return self._send(429, {"error": "rate limited"})
            length = int(self.headers.get("Content-Length", 0) or 0)
            raw = self.rfile.read(length) if length else b"{}"
            try:
                body = json.loads(raw or b"{}")
            except Exception:
                return self._send(400, {"error": "invalid json"})
            owner_key = self.headers.get("X-API-Key")
            status, payload = self.app.create_url(body, owner_key)
            return self._send(status, payload)
        return self._send(404, {"error": "not found"})

    def do_GET(self):
        if not self.app.limiter.allow(self._client_id()):
            return self._send(429, {"error": "rate limited"})
        m = ANALYTICS_RE.match(self.path)
        if m:
            status, payload = self.app.get_analytics(m.group(1))
            return self._send(status, payload)
        m = URL_ITEM_RE.match(self.path)
        if m:
            status, payload = self.app.get_url_info(m.group(1))
            return self._send(status, payload)
        if self.path in ("/", ""):
            return self._send(200, {"status": "ok"})
        short_code = self.path.lstrip("/")
        result = self.app.resolve(short_code)
        if result is None:
            return self._send(404, {"error": "not found"})
        if result == "EXPIRED":
            return self._send(410, {"error": "expired"})
        self.app.record_click(short_code, self.headers.get("Referer"), self.headers.get("User-Agent"))
        self.send_response(302)
        self.send_header("Location", result)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def do_DELETE(self):
        m = URL_ITEM_RE.match(self.path)
        if m:
            status, payload = self.app.delete_url(m.group(1))
            return self._send(status, payload)
        return self._send(404, {"error": "not found"})

    def log_message(self, fmt, *args):
        pass


def make_server(db_path=":memory:", host="127.0.0.1", port=0):
    app = Application(db_path)
    handler_cls = type("BoundHandler", (Handler,), {"app": app})
    server = ThreadingHTTPServer((host, port), handler_cls)
    return server, app


if __name__ == "__main__":
    srv, application = make_server(db_path="urls.db", port=8080)
    print("Serving on 8080")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        application.shutdown()
        srv.server_close()
